CREATE TABLE IF NOT EXISTS "UNIDADES_PLANIFICACION" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "CARGA_DOCENTE_ID" BIGINT NOT NULL,
    "NUMERO_UNIDAD" VARCHAR(30) NOT NULL,
    "NOMBRE" VARCHAR(180) NOT NULL,
    "SEMANA_INICIO" INTEGER,
    "FECHA_INICIO" DATE NOT NULL,
    "FECHA_TERMINO" DATE NOT NULL,
    "SEMANAS_ESTIMADAS" INTEGER NOT NULL DEFAULT 1,
    "CLASES_PLANIFICADAS" INTEGER NOT NULL DEFAULT 0,
    "DESCRIPCION_GENERAL" TEXT,
    "OBJETIVOS_APRENDIZAJE" TEXT,
    "INDICADORES_LOGRO" TEXT,
    "ESTADO" VARCHAR(20) NOT NULL,
    "CREADO_POR_USUARIO_ID" BIGINT NOT NULL,
    "FECHA_CREACION" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "FECHA_ACTUALIZACION" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "FK_UNIDADES_PLANIFICACION_CARGA_DOCENTE"
        FOREIGN KEY ("CARGA_DOCENTE_ID") REFERENCES "CARGAS_DOCENTES" ("ID"),
    CONSTRAINT "FK_UNIDADES_PLANIFICACION_USUARIO"
        FOREIGN KEY ("CREADO_POR_USUARIO_ID") REFERENCES "USUARIOS" ("ID"),
    CONSTRAINT "CHK_UNIDADES_PLANIFICACION_ESTADO"
        CHECK ("ESTADO" IN ('BORRADOR', 'CREADA', 'ACTIVA', 'COMPLETADA')),
    CONSTRAINT "CHK_UNIDADES_PLANIFICACION_SEMANAS"
        CHECK ("SEMANAS_ESTIMADAS" >= 1),
    CONSTRAINT "CHK_UNIDADES_PLANIFICACION_CLASES"
        CHECK ("CLASES_PLANIFICADAS" >= 0),
    CONSTRAINT "CHK_UNIDADES_PLANIFICACION_FECHAS"
        CHECK ("FECHA_TERMINO" >= "FECHA_INICIO")
);

CREATE INDEX IF NOT EXISTS "IDX_UNIDADES_PLANIFICACION_CARGA_DOCENTE"
    ON "UNIDADES_PLANIFICACION" ("CARGA_DOCENTE_ID");

CREATE INDEX IF NOT EXISTS "IDX_UNIDADES_PLANIFICACION_ESTADO"
    ON "UNIDADES_PLANIFICACION" ("ESTADO");

CREATE INDEX IF NOT EXISTS "IDX_UNIDADES_PLANIFICACION_CREADO_POR"
    ON "UNIDADES_PLANIFICACION" ("CREADO_POR_USUARIO_ID");

CREATE INDEX IF NOT EXISTS "IDX_UNIDADES_PLANIFICACION_FECHA_INICIO"
    ON "UNIDADES_PLANIFICACION" ("FECHA_INICIO");

INSERT INTO "UNIDADES_PLANIFICACION" (
    "CARGA_DOCENTE_ID",
    "NUMERO_UNIDAD",
    "NOMBRE",
    "SEMANA_INICIO",
    "FECHA_INICIO",
    "FECHA_TERMINO",
    "SEMANAS_ESTIMADAS",
    "CLASES_PLANIFICADAS",
    "DESCRIPCION_GENERAL",
    "OBJETIVOS_APRENDIZAJE",
    "INDICADORES_LOGRO",
    "ESTADO",
    "CREADO_POR_USUARIO_ID"
)
SELECT
    cd."ID",
    'UNIDAD_I',
    'El sistema solar y los movimientos de la Tierra',
    4,
    DATE '2026-04-13',
    DATE '2026-05-08',
    4,
    3,
    'Unidad introductoria para comprender el sistema solar, la rotacion y la traslacion.',
    'OA 5 - Describir las caracteristicas del sistema solar y su relacion con la Tierra.',
    'Reconoce los planetas, explica la rotacion y relaciona los movimientos de la Tierra con fenomenos observables.',
    'CREADA',
    u."ID"
FROM "CARGAS_DOCENTES" cd
JOIN "ASIGNATURAS" a ON a."ID" = cd."ASIGNATURA_ID"
JOIN "CURSOS" c ON c."ID" = cd."CURSO_ID"
JOIN "PROFESORES" pr ON pr."ID" = cd."PROFESOR_ID"
JOIN "USUARIOS" u ON u."PERSONA_ID" = pr."PERSONA_ID"
WHERE cd."ACTIVA" = TRUE
  AND a."ACTIVA" = TRUE
  AND c."ACTIVO" = TRUE
  AND u."USUARIO" = 'mgonzalez'
  AND NOT EXISTS (
      SELECT 1
      FROM "UNIDADES_PLANIFICACION" up
      WHERE up."CARGA_DOCENTE_ID" = cd."ID"
        AND up."NUMERO_UNIDAD" = 'UNIDAD_I'
        AND up."NOMBRE" = 'El sistema solar y los movimientos de la Tierra'
  )
LIMIT 1;
